def find_min(nums):
    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1                                        # rotation point is in the right half
        else:
            right = mid                                            # rotation point is at or before mid
    return nums[left]


if __name__ == "__main__":
    nums = [4, 5, 6, 7, 0, 1, 2]
    print(find_min(nums))

